scripts.training-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'training-store',
  description:
    "Read and update the training log (training.json). Call action:'status' for streak + this week vs the target; 'log_workout' the moment a session is reported (activity + minutes); 'set_target' to change the weekly session target; 'history' for the recent sessions; 'recap_numbers' for this week against last; 'save_recap' to write the weekly recap with one suggestion.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'log_workout', 'set_target', 'history', 'recap_numbers', 'request_recap', or 'save_recap'.",
      required: true,
    },
    activity: { type: 'string', description: "What they did, e.g. 'run', 'gym', 'long walk'." },
    minutes: { type: 'number', description: 'How long the session ran, in minutes.' },
    note: { type: 'string', description: 'Anything worth remembering about the session.' },
    weeklyTarget: { type: 'number', description: 'Sessions per week to aim for (set_target).' },
    suggestion: { type: 'string', description: 'For save_recap: one concrete suggestion for next week.' },
  },
  outputs: {
    streakDays: { type: 'number', description: 'Consecutive days with a session, ending at the latest.' },
    thisWeek: { type: 'number', description: 'Sessions logged this week (Monday UTC start).' },
    weeklyTarget: { type: 'number', description: 'The current weekly session target.' },
    summary: { type: 'string', description: 'The training picture.' },
    personalBest: { type: 'boolean', description: 'For log_workout: the longest session on record.' },
    recap: { type: 'json', description: 'This week against last: sessions, minutes, longest session.' },
    display: { type: 'string', description: 'For save_recap: the recap as shown.' },
    status: { type: 'string', description: "'recap_wanted' after request_recap, else 'ok'." },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── fitness-rules-start ──
// Pure derivations over logStore-shaped workout events: kind 'workout',
// data {activity, minutes}. Weeks start Monday 00:00 UTC; nowIso is a
// parameter so the rules stay clock-independent and testable.

function weekStartMs(nowIso) {
  var day = new Date(nowIso.slice(0, 10) + 'T00:00:00Z');
  var sinceMonday = (day.getUTCDay() + 6) % 7;
  return day.getTime() - sinceMonday * 86400000;
}

function thisWeekCount(events, nowIso) {
  var start = weekStartMs(nowIso);
  return events.filter(function (e) {
    return Date.parse(e.at) >= start;
  }).length;
}

function trainingLine(stats, weekCount, weeklyTarget) {
  var target = weeklyTarget > 0 ? weeklyTarget : 0;
  var weekPart =
    'This week: ' +
    weekCount +
    (target > 0 ? ' of ' + target + ' session(s)' : ' session(s)') +
    (target > 0 && weekCount >= target ? ' — target met.' : '.');
  var streakPart =
    stats.total === 0
      ? 'No sessions logged yet.'
      : 'Streak: ' + stats.streakDays + ' day(s); ' + stats.total + ' session(s) all time.';
  return weekPart + ' ' + streakPart;
}

// The week's numbers against the week before: what a recap reports, so the
// coach only adds a suggestion. Weeks start Monday UTC, as above.
function weekRecap(events, nowIso, weeklyTarget) {
  var start = weekStartMs(nowIso);
  var prevStart = start - 7 * 86400000;
  function minutesOf(e) {
    var m = e.data && Number(e.data.minutes);
    return isFinite(m) && m > 0 ? m : 0;
  }
  var week = events.filter(function (e) { return Date.parse(e.at) >= start; });
  var prev = events.filter(function (e) {
    var t = Date.parse(e.at);
    return t >= prevStart && t < start;
  });
  var minutes = week.reduce(function (n, e) { return n + minutesOf(e); }, 0);
  var prevMinutes = prev.reduce(function (n, e) { return n + minutesOf(e); }, 0);
  var longest = week.reduce(function (best, e) {
    return !best || minutesOf(e) > minutesOf(best) ? e : best;
  }, null);
  return {
    weekOf: new Date(start).toISOString().slice(0, 10),
    sessions: week.length,
    target: weeklyTarget,
    minutes: minutes,
    sessionsChange: week.length - prev.length,
    minutesChange: minutes - prevMinutes,
    longest: longest
      ? { activity: String((longest.data && longest.data.activity) || 'session'), minutes: minutesOf(longest) }
      : null,
  };
}

function recapLine(recap, suggestion) {
  var change = recap.minutesChange === 0 ? 'same as last week' : (recap.minutesChange > 0 ? '+' : '') + recap.minutesChange + ' min vs last week';
  return (
    'Week of ' + recap.weekOf + ': ' + recap.sessions + (recap.target > 0 ? ' of ' + recap.target : '') +
    ' session(s), ' + recap.minutes + ' min (' + change + ').' +
    (suggestion ? ' Next week: ' + suggestion : '')
  );
}
// ── fitness-rules-end ──

const training = logStore(gezel.fs, 'training.json');

async function readWeeklyTarget(): Promise<number> {
  try {
    const parsed = JSON.parse(await gezel.fs.read('training.json')) as { weeklyTarget?: unknown };
    const target = Number(parsed.weeklyTarget);
    return Number.isFinite(target) && target > 0 ? Math.round(target) : 0;
  } catch {
    return 0;
  }
}

let personalBest = false;
let display = '';
let status = 'ok';
if (input.action === 'log_workout') {
  if (!input.activity) throw new Error("log_workout needs 'activity' (what they did).");
  const minutes = typeof input.minutes === 'number' && input.minutes > 0 ? Math.round(input.minutes) : 0;
  const before = await training.list();
  const longestBefore = before.reduce((n, e) => Math.max(n, Number(e.data?.minutes) || 0), 0);
  personalBest = minutes > 0 && before.length > 0 && minutes > longestBefore;
  await training.append({
    kind: 'workout',
    ...(input.note ? { note: input.note } : {}),
    data: {
      activity: input.activity,
      ...(typeof input.minutes === 'number' && input.minutes > 0
        ? { minutes: Math.round(input.minutes) }
        : {}),
    },
  });
} else if (input.action === 'set_target') {
  const target = Number(input.weeklyTarget);
  if (!Number.isFinite(target) || target <= 0) {
    throw new Error("set_target needs a positive 'weeklyTarget' (sessions per week).");
  }
  // logStore has no field API; the passenger key flips via a targeted
  // read-modify-write that preserves the rest of the file.
  const raw = JSON.parse(await gezel.fs.read('training.json')) as Record<string, unknown>;
  raw.weeklyTarget = Math.round(target);
  await gezel.fs.write('training.json', `${JSON.stringify(raw, null, 2)}\n`);
} else if (input.action === 'request_recap') {
  status = 'recap_wanted';
} else if (input.action === 'save_recap') {
  const suggestion = String(input.suggestion ?? '').replace(/\s+/g, ' ').trim().slice(0, 240);
  if (suggestion.length < 10) throw new Error("save_recap needs a one-sentence 'suggestion' for next week.");
  const recap = weekRecap(await training.list(), new Date().toISOString(), await readWeeklyTarget());
  const doc = { ...recap, suggestion, writtenAt: new Date().toISOString() };
  const body = `${JSON.stringify(doc, null, 2)}\n`;
  await gezel.fs.write(`recaps/${recap.weekOf}.json`, body);
  await gezel.fs.write('recaps/latest.json', body);
  display = recapLine(recap, suggestion);
} else if (!['status', 'history', 'recap_numbers'].includes(String(input.action))) {
  throw new Error(
    `Unknown action '${input.action}'. Use status, log_workout, set_target, history, recap_numbers, or save_recap.`,
  );
}

const events = await training.list();
const stats = await training.stats();
const weeklyTarget = await readWeeklyTarget();
const nowIso = new Date().toISOString();
const weekCount = thisWeekCount(events, nowIso);
const listing =
  input.action === 'history'
    ? events
        .slice(-12)
        .map(
          (e) =>
            `${e.at.slice(0, 10)} ${String(e.data?.activity ?? 'session')}${typeof e.data?.minutes === 'number' ? ` (${e.data.minutes} min)` : ''}${e.note ? ` — ${e.note}` : ''}`,
        )
        .join('\n') || 'No sessions yet.'
    : '';

const recap = weekRecap(events, nowIso, weeklyTarget);
gezel.output({
  streakDays: stats.streakDays,
  thisWeek: weekCount,
  weeklyTarget,
  summary:
    listing ||
    (input.action === 'recap_numbers' || input.action === 'request_recap'
      ? recapLine(recap, '')
      : trainingLine(stats, weekCount, weeklyTarget)),
  personalBest,
  recap,
  display,
  status,
});
